class Settings(dict):

    def __getattr__(self, item):
        return self.get(item)

    def update(self, **kwargs):
        """Returns new settings with new values from `kwargs`."""
        conf = dict(self)
        conf.update(kwargs)
        return Settings(conf)


def solve(existing, defaults, lookups):
    settings = Settings(existing)
    merged = settings.update(**defaults)
    return {"original": dict(settings), "merged": dict(merged), "lookups": [getattr(merged, key) for key in lookups]}
